"""Byte-compatible EXPORT_ACCT fixed-width record formatter."""

from decimal import Decimal, ROUND_HALF_UP, localcontext


def _empty(value: object) -> bool:
    return value is None or value == ""


def _fixed(value: object, width: int) -> str:
    text = "" if _empty(value) else str(value)
    return text[:width].ljust(width)


def _integer_cents(value: object) -> int:
    if _empty(value):
        return 0

    # str() avoids binary floating-point rounding behavior for float inputs.
    amount = Decimal(str(value))
    with localcontext() as context:
        context.prec = max(28, len(amount.as_tuple().digits) + 4)
        cents = (amount * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
    return int(cents)


def _zpad_cents(value: object, width: int) -> str:
    return str(_integer_cents(value)).zfill(width)


def format_account(row: dict) -> str:
    """Build one 77-character EXPORT_ACCT record without a record terminator."""
    acct_id = row.get("ACCT_ID", "")
    acct_name = row.get("ACCT_NM", "")
    region = row.get("REGION_CD", "")
    annual_revenue = row.get("ANN_REV", "")
    credit_hold = row.get("CRED_HOLD", "")
    create_date = row.get("CREATE_DT", "")

    if _empty(credit_hold):
        credit_hold = "N"
    if _empty(create_date):
        create_date = "00000000"

    return (
        _fixed(acct_id, 10)
        + _fixed(acct_name, 40)
        + _fixed(region, 3)
        + _zpad_cents(annual_revenue, 15)
        + str(credit_hold)
        + str(create_date)
    )
